// piper writes a WAV file to stdout, so models with any sample rate can share
// one command. If sox is available on the host system we use it to adjust
// pitch and rate. Otherwise, we pass the output unmodified to either paplay
// or aplay depending on what is available on the system.
//
// $VOICE is "model" or "model:speaker" (see piper_config.dart). The shell
// variables avoid the ${...} form, which the configuration parser of
// Speech Dispatcher replaces with environment variables.
const String modelTemplate = """
###
### THIS CONFIG WAS GENERATED BY PIED
###

GenericExecuteSynth "V=\\'\$VOICE\\'; M=\$(echo \$V | cut -d: -f1); S=\$(echo \$V:0 | cut -d: -f2);\\
    if command -v sox > /dev/null; then\\
        PROCESS=\\'sox -t wav - -t wav - tempo \$RATE pitch \$PITCH\\';\\
        if command -v paplay > /dev/null; then\\
            OUTPUT=\\'\$PLAY_COMMAND\\';\\
        else\\
            OUTPUT=\\'aplay\\';\\
        fi;\\
    elif command -v paplay > /dev/null; then\\
        PROCESS=\\'cat\\'; OUTPUT=\\'\$PLAY_COMMAND\\';\\
    else\\
        PROCESS=\\'cat\\'; OUTPUT=\\'aplay\\';\\
    fi;\\
    echo \\'\$DATA\\' | PIPER_PATH --model MODEL_DIR/\$M.onnx -s \$S --output_file - | \$PROCESS | \$OUTPUT;"
GenericRateAdd 1
GenericPitchAdd 1
GenericVolumeAdd 1
GenericRateMultiply 1
GenericPitchMultiply 1000

GenericDelimiters "˨"
GenericMaxChunkLength 1000000
""";

